<script setup lang="ts">
import { onMounted,ref } from 'vue';import { api } from '@/api/http';import { useUserStore } from '@/stores/user';import type { Order } from '@/types'
const user=useUserStore(),orders=ref<Order[]>([]),loading=ref(false);const labels:Record<string,string>={PENDING_PAYMENT:'待付款',PENDING_ACCEPTANCE:'商家待接单',PREPARING:'制作中',PENDING_DELIVERY:'待配送',DELIVERING:'配送中',COMPLETED:'已完成',CANCELLED:'已取消'}
async function load(){loading.value=true;try{if(!user.loggedIn)await user.login();orders.value=await api<Order[]>({url:'/user/orders'})}finally{loading.value=false}}async function pay(order:Order){const result=await api<{mode:string;status:string}>({url:`/user/orders/${order.id}/payment`,method:'POST'});if(result.status==='PAID')await load();else alert('真实微信支付请在微信小程序中完成')}
onMounted(load)
</script>
<template><section class="orders-page"><div class="page-title"><span>ORDER HISTORY</span><h1>我的订单</h1><p>随时查看制作与配送进度。</p></div><div v-if="loading" class="state">正在加载订单…</div><div v-else-if="!orders.length" class="state">暂无订单，先去挑选一份好味道吧。</div><article v-for="o in orders" class="order-card"><header><div><b>订单 {{o.orderNumber}}</b><small>{{o.createdTime?.replace('T',' ')}}</small></div><span>{{labels[o.status]||o.status}}</span></header><div class="order-lines"><p v-for="d in o.details"><span>{{d.name}} × {{d.quantity}}</span><strong>¥{{d.amount}}</strong></p></div><footer><span>合计 <b>¥{{o.amount}}</b></span><button v-if="o.status==='PENDING_PAYMENT'" @click="pay(o)">立即付款</button></footer></article></section></template>
